const ASSIGNED_TARGETS = PLAYABLE_TARGETS.filter(({ batchId }) => batchId === '02-geography');
const CATEGORY_SEEDS = [
  ...MEDIUM_CATEGORIES,
  ...MEDIUM_CATEGORIES_2,
  ...MEDIUM_CATEGORIES_3,
  ...HARD_CATEGORIES,
  ...HARD_CATEGORIES_2,
  ...HARD_CATEGORIES_3,
] as const satisfies readonly CategorySeed[];

function variants(value: string): readonly string[] {
  return value.split('|').map((item) => item.trim()).filter(Boolean);
}

function buildQuestion(
  categorySetId: string,
  seed: QuestionSeed,
  tierIndex: number,
): PlayableQuestion {
  const [
    factKey,
    subjectKey,
    clueEn,
    clueEt,
    responseEn,
    responseEt,
    variantsEn,
    variantsEt,
    explanationEn,
    explanationEt,
    sourceTitle,
    sourcePath,
  ] = seed;
  const sourceUrl = sourcePath.startsWith('https://')
    ? sourcePath
    : `https://en.wikipedia.org/wiki/${sourcePath}`;
  return {
    key: `playable-geography:${categorySetId}:${factKey}`,
    factKey: `geography:${factKey}`,
    tier: (tierIndex + 1) as 1 | 2 | 3 | 4 | 5,
    subjectKey,
    clue: { en: clueEn, et: clueEt },
    response: { en: responseEn, et: responseEt },
    acceptedVariants: { en: variants(variantsEn), et: variants(variantsEt) },
    explanation: { en: explanationEn, et: explanationEt },
    source: {
      sourceId: `wikipedia:${sourcePath.toLocaleLowerCase('en')}`,
      title: sourceTitle,
      url: sourceUrl,
      license: 'CC-BY-SA-4.0',
      retrievedAt: '2026-08-28',
    },
  };
}

const rawCategories: readonly PlayableCategory[] = CATEGORY_SEEDS.map((seed) => {
  const target = ASSIGNED_TARGETS.find(({ categorySetId }) => categorySetId === seed.categorySetId);
  if (target === undefined) throw new Error(`Missing assigned target ${seed.categorySetId}`);
  return {
    categorySetId: seed.categorySetId,
    batchId: target.batchId,
    packId: target.packId,
    difficulty: target.difficulty,
    name: { en: seed.nameEn, et: seed.nameEt },
    questions: seed.questions.map((question, index) =>
      buildQuestion(seed.categorySetId, question, index)),
  };
});

export const GEOGRAPHY_CATEGORIES = validatePlayableCorpus(rawCategories, ASSIGNED_TARGETS);
